const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const sacramento = ee.Geometry.Point([-121.4944, 38.5816]); // Sacramento, CA
  const buffer = sacramento.buffer(5000); // 5km buffer around Sacramento
  const startDate = '2022-09-01';
  const endDate = '2022-09-30';

  // 2. Data Acquisition
  const tempCollection = ee.ImageCollection('ECMWF/ERA5/DAILY')
    .filterDate(startDate, endDate)
    .filterBounds(buffer)
    .select('mean_2m_air_temperature');

  const collectionSize = tempCollection.size().getInfo();
  console.log(`September 2022 temperature images: ${collectionSize}`);

  if (collectionSize === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Calculate maximum temperature for the month
  const maxTempImage = tempCollection.max();

  // 4. Get pixel count and temperature values
  const stats = maxTempImage.reduceRegion({
    reducer: ee.Reducer.count().combine({
      reducer2: ee.Reducer.max(),
      sharedInputs: true
    }),
    geometry: buffer,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const pixelCount = stats['mean_2m_air_temperature_count'];
  const maxTempK = stats['mean_2m_air_temperature_max'];

  console.log(`Valid pixels: ${pixelCount}`);
  console.log(`Max temperature (K): ${maxTempK ? maxTempK.toFixed(2) : 'null'}`);

  if (pixelCount === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  if (maxTempK === null || maxTempK === undefined || !isFinite(maxTempK)) {
    console.log("<answer>C3</answer>");
    return;
  }

  // Convert Kelvin to Fahrenheit
  const maxTempF = (maxTempK - 273.15) * 9/5 + 32;
  console.log(`Max temperature (°F): ${maxTempF.toFixed(2)}`);

  // 5. Validation & Final Answer
  if (maxTempF > 110) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
